def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == 'numeric':
        return '.'.join(map(str, pieces))
    elif style == 'dotted':
        return '-'.join(map(str, pieces))
    elif style == 'semantic':
        return '.'.join(map(str, pieces[:3])) + ('-' + pieces[3] if len(pieces) > 3 else '')
    else:
        raise ValueError("Unsupported style: {}".format(style))

