def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse the document as JSON
        parsed_document = json.loads(document)
        return parsed_document
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XML (XRD)
        try:
            root = ET.fromstring(document)
            # Extract relevant information from XRD XML
            hcard_url = root.find(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link[@rel='http://microformats.org/profile/hcard']").attrib.get('href')
            return {"hcard_url": hcard_url}
        except (ET.ParseError, AttributeError):
            # If XML parsing fails or element is not found, return an empty dictionary
            return {}

