def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg_name, (value, spec) in args.items():
        min_value = spec.get('min')
        max_value = spec.get('max')
        if min_value is not None and value < min_value:
            raise ValueError(f"The value of '{arg_name}' must be at least {min_value}.")
        if max_value is not None and value > max_value:
            raise ValueError(f"The value of '{arg_name}' must be at most {max_value}.")

